example.example:
   match को आधारभूत प्रयोग


<?php
$food = 'cake';

$return_value = match ($food) {
    'apple' => 'This food is an apple',
    'bar' => 'This food is a bar',
    'cake' => 'This food is a cake',
};

var_dump($return_value);
?>


  &example.outputs;


string(19) "This food is a cake"

   Comparison operators सँग match को प्रयोग


<?php
$age = 18;

$output = match (true) {
    $age < 2 => "Baby",
    $age < 13 => "Child",
    $age <= 19 => "Teenager",
    $age >= 40 => "Adult",
    $age > 19 => "Young adult",
};

var_dump($output);
?>


  &example.outputs;


string(8) "Teenager"

sect1.para:
  switch statements जस्तै, match expressions पनि arm-by-arm चल्छन्।
  सुरुआतमा कुनै पनि code चल्दैन।
  अघिल्ला सबै शर्तहरू subject expression सँग मेल नखाएको अवस्थामा मात्र पछिल्ला conditional expressions evaluate गरिन्छन्।
  मेल खाएको conditional expression सँग सम्बन्धित return expression मात्र evaluate हुन्छ।
  उदाहरणका लागि:



<?php
$result = match ($x) {
    foo() => 'value',
    $this->bar() => 'value', // foo() === $x भएमा $this->bar() call हुँदैन
    $this->baz => beep(), // $x === $this->baz नभएसम्म beep() call हुँदैन
    // आदि।
};
?>

sect1.example:
  Unhandled match expression को उदाहरण


<?php
$condition = 5;

try {
    match ($condition) {
        1, 2 => foo(),
        3, 4 => bar(),
    };
} catch (UnhandledMatchError $e) {
    var_dump($e);
}
?>


  &example.outputs;


object(UnhandledMatchError)#1 (7) {
  ["message":protected]=>
  string(22) "Unhandled match case 5"
  ["string":"Error":private]=>
  string(0) ""
  ["code":protected]=>
  int(0)
  ["file":protected]=>
  string(6) "script"
  ["line":protected]=>
  int(5)
  ["trace":"Error":private]=>
  array(0) {
  }
  ["previous":"Error":private]=>
  NULL
}

sect2.example:
   Integer ranges मा शाखा विभाजन गर्न सामान्यीकृत match expression को प्रयोग


<?php
$age = 23;

$result = match (true) {
    $age >= 65 => 'senior',
    $age >= 25 => 'adult',
    $age >= 18 => 'young adult',
    default => 'kid',
};

var_dump($result);
?>


   &example.outputs;


string(11) "young adult"

   String content मा शाखा विभाजन गर्न सामान्यीकृत match expression को प्रयोग


<?php

$text = 'Bienvenue chez nous';

$result = match (true) {
    str_contains($text, 'Welcome'), str_contains($text, 'Hello') => 'en',
    str_contains($text, 'Bienvenue'), str_contains($text, 'Bonjour') => 'fr',
    // ...
};

var_dump($result);
?>


   &example.outputs;


string(2) "fr"
